def footer(canvas, doc):
    canvas.saveState()
    canvas.setStrokeColor(colors.HexColor('#b6c5d0'))
    canvas.line(48,39,564,39)
    canvas.setFont('DejaVu',7)
    canvas.setFillColor(colors.HexColor('#46596a'))
